<?php
declare(strict_types=1);
const LC_INSTALL_ROOT = __DIR__ . '/..';
foreach ([LC_INSTALL_ROOT.'/.env', dirname(LC_INSTALL_ROOT).'/.env'] as $env) if (is_file($env)) foreach (file($env, FILE_IGNORE_NEW_LINES) as $line) if (preg_match('/^([A-Z][A-Z0-9_]*)=(.*)$/', trim($line), $m) && getenv($m[1]) === false) putenv($m[1].'='.trim(trim($m[2]), "\"'"));
function li_env(string $key,string $default=''):string{$v=getenv($key);return $v===false||$v===''?$default:$v;}
function li_db():PDO{static $db;if(!$db){$path=li_env('LICENSE_DB_PATH',LC_INSTALL_ROOT.'/storage/licenses.sqlite');if(!is_dir(dirname($path)))mkdir(dirname($path),0700,true);$db=new PDO('sqlite:'.$path,null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);}$db->exec('PRAGMA foreign_keys=ON');return $db;}
function li_requirements():array{$storage=li_env('LICENSE_STORAGE_PATH',LC_INSTALL_ROOT.'/storage');return ['PHP 8.2+'=>version_compare(PHP_VERSION,'8.2.0','>='),'PDO SQLite'=>extension_loaded('pdo_sqlite'),'SQLite3'=>extension_loaded('sqlite3'),'cURL'=>extension_loaded('curl'),'OpenSSL'=>extension_loaded('openssl'),'JSON'=>extension_loaded('json'),'Mbstring'=>extension_loaded('mbstring'),'Storage writable'=>is_dir($storage)?is_writable($storage):is_writable(dirname($storage)),'HTTPS or local'=>!empty($_SERVER['HTTPS'])||in_array($_SERVER['SERVER_NAME']??'', ['localhost','127.0.0.1'], true)];}
function li_html(string $title,string $body):never{echo '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.htmlspecialchars($title,ENT_QUOTES,'UTF-8').' · TofiDesk</title><style>body{font:16px/1.5 Arial;background:#f4f6f5;color:#08283a;margin:0}.box{max-width:760px;margin:50px auto;padding:32px;background:#fff;border:1px solid #dfe6e8;border-radius:14px}li{padding:8px 0} .ok{color:#16834b}.bad{color:#b42318}label{display:block;margin:13px 0;font-weight:700}input{display:block;width:100%;box-sizing:border-box;padding:11px;margin-top:5px}button{background:#ff7c2c;border:0;border-radius:7px;padding:12px 18px;font-weight:700}</style><main class="box"><h1>'.htmlspecialchars($title,ENT_QUOTES,'UTF-8').'</h1>'.$body.'</main></html>';exit;}
$token=li_env('LICENSE_INSTALL_TOKEN');if($token===''||!hash_equals($token,(string)($_GET['token']??$_POST['token']??'')))li_html('Installation token required','<p>Set LICENSE_INSTALL_TOKEN in the private environment and open this page with <code>?token=...</code>.</p>');
$checks=li_requirements();$errors=array_keys(array_filter($checks,static fn(bool $ok):bool=>!$ok));if($errors)li_html('Server requirements','<p class="bad">Resolve these requirements before continuing:</p><ul>'.implode('',array_map(static fn(string $name):string=>'<li class="bad">✗ '.htmlspecialchars($name,ENT_QUOTES,'UTF-8').'</li>',$errors)).'</ul>');
try{li_db()->exec('CREATE TABLE IF NOT EXISTS admins(id INTEGER PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)');if(li_db()->query('SELECT id FROM admins LIMIT 1')->fetch()){li_html('Already installed','<p>This license centre already has an administrator. <a href="./login">Go to login</a>.</p>');}}catch(Throwable $e){li_html('Database check failed','<p class="bad">'.htmlspecialchars($e->getMessage(),ENT_QUOTES,'UTF-8').'</p>');}
if($_SERVER['REQUEST_METHOD']==='POST'){$email=filter_var(trim((string)($_POST['email']??'')),FILTER_VALIDATE_EMAIL);$password=(string)($_POST['password']??'');if(!$email||strlen($password)<12)li_html('Invalid setup','<p class="bad">Use a valid email and a password of at least 12 characters.</p>');$stmt=li_db()->prepare('INSERT INTO admins(email,password_hash) VALUES(?,?)');$stmt->execute([$email,password_hash($password,PASSWORD_DEFAULT)]);header('Location: ./login');exit;}
$items='';foreach($checks as $name=>$ok)$items.='<li class="'.($ok?'ok':'bad').'">'.($ok?'✓':'✗').' '.htmlspecialchars($name,ENT_QUOTES,'UTF-8').'</li>';li_html('TofiDesk License Centre installer','<p>Server check passed. Create the first administrator.</p><ul>'.$items.'</ul><form method="post"><input type="hidden" name="token" value="'.htmlspecialchars($token,ENT_QUOTES,'UTF-8').'"><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" minlength="12" required></label><button>Create administrator</button></form>');
